BEGIN;
CREATE TABLE IF NOT EXISTS fleet_vehicles(id uuid PRIMARY KEY,plate text NOT NULL UNIQUE,brand text NOT NULL,model text NOT NULL,model_year integer NOT NULL CHECK(model_year BETWEEN 1900 AND 2200),vin text UNIQUE,fuel text NOT NULL,km integer NOT NULL CHECK(km>=0),company_id uuid NOT NULL REFERENCES companies,location_id uuid NOT NULL REFERENCES locations,status text NOT NULL DEFAULT 'POOL' CHECK(status IN('ASSIGNED','POOL','SERVICE','FAULTY','INACTIVE')),registration text NOT NULL DEFAULT '',insurance_end date,casco_end date,inspection_date date,last_service_date date,next_service_date date,next_service_km integer,tires text NOT NULL DEFAULT '',hgs_reference text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS fleet_allocations(id uuid PRIMARY KEY,vehicle_id uuid NOT NULL REFERENCES fleet_vehicles,user_id uuid NOT NULL REFERENCES users,assigned_by uuid NOT NULL REFERENCES users,start_at timestamptz NOT NULL DEFAULT now(),start_km integer NOT NULL CHECK(start_km>=0),note text NOT NULL DEFAULT '',end_at timestamptz,received_by uuid REFERENCES users,end_km integer,return_note text NOT NULL DEFAULT '',CHECK((end_at IS NULL AND received_by IS NULL AND end_km IS NULL) OR (end_at>=start_at AND received_by IS NOT NULL AND end_km>=start_km)));
CREATE UNIQUE INDEX IF NOT EXISTS fleet_one_active ON fleet_allocations(vehicle_id) WHERE end_at IS NULL;
CREATE INDEX IF NOT EXISTS fleet_allocation_user ON fleet_allocations(user_id,start_at);
CREATE INDEX IF NOT EXISTS fleet_vehicle_org ON fleet_vehicles(company_id,location_id,status);
CREATE INDEX IF NOT EXISTS fleet_due_dates ON fleet_vehicles(insurance_end,casco_end,inspection_date,next_service_date);
CREATE TABLE IF NOT EXISTS fleet_files(id uuid PRIMARY KEY,vehicle_id uuid NOT NULL REFERENCES fleet_vehicles,kind text NOT NULL CHECK(kind IN('IMAGE','DOCUMENT')),file jsonb NOT NULL,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS fleet_files_vehicle ON fleet_files(vehicle_id);
CREATE TABLE IF NOT EXISTS fleet_service_history(id uuid PRIMARY KEY,vehicle_id uuid NOT NULL REFERENCES fleet_vehicles,kind text NOT NULL CHECK(kind IN('MAINTENANCE','FAULT','SERVICE','ACCIDENT')),date date NOT NULL,km integer NOT NULL CHECK(km>=0),provider text NOT NULL,description text NOT NULL,cost numeric(14,2) CHECK(cost>=0),document jsonb,next_service_date date,next_service_km integer,actor_id uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS fleet_service_vehicle ON fleet_service_history(vehicle_id,date);
CREATE OR REPLACE FUNCTION fleet_consistency() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE target uuid; actual text; assigned boolean; BEGIN IF TG_TABLE_NAME='fleet_vehicles' THEN target:=NEW.id;ELSE target:=NEW.vehicle_id;END IF; SELECT status INTO actual FROM fleet_vehicles WHERE id=target;SELECT EXISTS(SELECT 1 FROM fleet_allocations WHERE vehicle_id=target AND end_at IS NULL) INTO assigned;IF (actual='ASSIGNED') IS DISTINCT FROM assigned THEN RAISE EXCEPTION 'Fleet allocation mismatch' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
DROP TRIGGER IF EXISTS fleet_vehicle_consistency ON fleet_vehicles;
CREATE CONSTRAINT TRIGGER fleet_vehicle_consistency AFTER INSERT OR UPDATE ON fleet_vehicles DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fleet_consistency();
DROP TRIGGER IF EXISTS fleet_allocation_consistency ON fleet_allocations;
CREATE CONSTRAINT TRIGGER fleet_allocation_consistency AFTER INSERT OR UPDATE ON fleet_allocations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION fleet_consistency();
CREATE OR REPLACE FUNCTION fleet_allocation_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR OLD.end_at IS NOT NULL OR (NEW.vehicle_id,NEW.user_id,NEW.assigned_by,NEW.start_at,NEW.start_km) IS DISTINCT FROM (OLD.vehicle_id,OLD.user_id,OLD.assigned_by,OLD.start_at,OLD.start_km) THEN RAISE EXCEPTION 'Allocation history immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS fleet_allocation_guard ON fleet_allocations;
CREATE TRIGGER fleet_allocation_guard BEFORE UPDATE OR DELETE ON fleet_allocations FOR EACH ROW EXECUTE FUNCTION fleet_allocation_guard();
DROP TRIGGER IF EXISTS fleet_service_immutable ON fleet_service_history;
CREATE TRIGGER fleet_service_immutable BEFORE UPDATE OR DELETE ON fleet_service_history FOR EACH ROW EXECUTE FUNCTION workflow_immutable();
DROP TRIGGER IF EXISTS fleet_file_immutable ON fleet_files;
CREATE TRIGGER fleet_file_immutable BEFORE UPDATE OR DELETE ON fleet_files FOR EACH ROW EXECUTE FUNCTION workflow_immutable();
COMMIT;
